const expected = String($env.N8N_PROXY_SECRET || '');
const supplied = String(($json.headers || {})['x-n8n-proxy-secret'] || '');
return [{ json: { ...$json, proxy_authorized: Boolean(expected && supplied === expected) } }];

// Unwrap the POST body and compute the 7 dates of week 1 (starting today).
// The landing page enforces field presence; we stay defensive with fallbacks.

const p = $json.body || $json;
const dates = [];
for (let i = 0; i < 7; i++) dates.push($now.plus({ days: i }).toISODate());

return [{ json: {
  user: p.user || {},
  questionnaire: p.questionnaire || {},
  prescription_input: p.prescription_input || {},
  week1_dates: dates,
  week1_start: dates[0],
  week1_end: dates[6]
} }];

// Build the Gemini vision request: instruction text + enums + context, plus the
// prescription image as inline_data when present. Output is a JSON string the
// HTTP node posts verbatim. No apostrophes/backticks in code strings (escaping).
//
// Taxonomy split: pillar and category stay locked enums on the prescription; the
// concrete execution step is action_text, drafted per nudge and freely revised by
// the clinician at review. There is no fixed action catalogue any more.

const c = $json;
const q = c.questionnaire || {};
const pi = c.prescription_input || {};

const ENUMS = {
  pillar: ['nutrition','physical_activity','sleep','stress_management','substance_use','social_connection'],
  category: ['increase','reduce','maintain','avoid','establish'],
  nudge_type: ['reminder','reflection','challenge','affirmation'],
  tone_variant: ['encouraging','neutral_informational'],
  template_name: ['health_plan_reminder','hello_world']
};

const context = {
  patient: { age: q.age, gender: q.gender, activity_level: q.activity_level, primary_goal: q.primary_goal, preferred_nudge_time: q.preferred_nudge_time },
  prescription_free_text: pi.prescription_raw_text || '',
  has_prescription_image: !!pi.prescription_image_base64,
  week1_dates: c.week1_dates
};

const rules = [
  'Read the doctor prescription from the free text AND the attached image if present. The image is authoritative when present.',
  'Extract one or more canonical prescription objects using the exact enum tokens for pillar and category.',
  'Give each prescription a temporary ref (p1, p2, ...). Each nudge links to its prescription via prescription_ref.',
  'For EACH prescription generate WEEK 1 nudges only: exactly frequency_per_week nudges, each on a distinct date from week1_dates.',
  'Every nudge needs action_text: the concrete step the patient performs, in plain clinical English, 120 chars or fewer, e.g. Walk for 20 minutes after dinner. It is free text, NOT an enum, and must be specific enough to act on without reading the message.',
  'action_text describes WHAT the patient does; message_body describes HOW it is communicated. Never put the whole message in action_text.',
  'Nudges under one prescription may carry different action_text when the doctor described different steps for the same behaviour.',
  'scheduled_time defaults to the patient preferred_nudge_time in HH:MM 24h.',
  'Write TWO bodies per nudge: message_body (tone equals tone_variant) and message_body_alt (the opposite tone). Each 180 chars or fewer, plain WhatsApp-safe text.',
  'A nudge pillar MUST equal its prescription pillar.',
  'template_name must be health_plan_reminder for every nudge.',
  'Output STRICT JSON only, no markdown: { prescriptions: [...], nudges: [...] }.',
  'prescription fields: ref, pillar, category, frequency_per_week (int 1-7), duration_weeks (int 1-52).',
  'nudge fields: prescription_ref, pillar, nudge_type, action_text, scheduled_date (a value from week1_dates), scheduled_time (HH:MM), tone_variant, message_body, message_body_alt, template_name.'
];

const promptText =
  'You convert a real doctor lifestyle prescription into a structured, dated first-week nudge schedule.\n\n' +
  'ALLOWED ENUMS (use these tokens verbatim):\n' + JSON.stringify(ENUMS) + '\n\n' +
  'CONTEXT:\n' + JSON.stringify(context) + '\n\n' +
  'RULES:\n' + rules.map((r, i) => (i + 1) + '. ' + r).join('\n') + '\n\nReturn JSON only.';

const parts = [{ text: promptText }];
if (pi.prescription_image_base64) {
  parts.push({ inline_data: { mime_type: pi.prescription_image_mimetype || 'image/jpeg', data: pi.prescription_image_base64 } });
}

const body = {
  contents: [{ parts }],
  generationConfig: { responseMimeType: 'application/json', temperature: 0.4, maxOutputTokens: 8192, thinkingConfig: { thinkingBudget: 0 } }
};

return [{ json: { gemini_body: JSON.stringify(body) } }];

// Gemini occasionally returns a category that is not one of the five allowed
// tokens. Correct only that known, deterministic mismatch: case/spacing drift,
// and the retired fixed-action tokens it still emits from pre-change habits.
// action_text is clinician free text and is never rewritten here. The downstream
// validation gate still rejects every other invalid value and prevents partial writes.
const resp = items[0].json;
const allowed = new Set(['increase','reduce','maintain','avoid','establish']);
const pillars = new Set(['nutrition','physical_activity','sleep','stress_management','substance_use','social_connection']);
const tidy = v => String(v == null ? '' : v).trim().toLowerCase().replace(/[\s-]+/g, '_');
// Retired target_behavior enum, kept only as a drift map: a leftover action token
// in category still resolves to the category that token always implied.
const categoryByBehavior = {
  daily_steps_10000: 'increase', daily_steps_7500: 'increase', daily_steps_5000: 'increase',
  aerobic_exercise_30min: 'increase', aerobic_exercise_20min: 'increase',
  resistance_training_2x_week: 'increase', resistance_training_3x_week: 'increase',
  vegetable_servings_5_per_day: 'increase', fruit_servings_2_per_day: 'increase',
  water_intake_2L_per_day: 'increase', social_activity_1x_week: 'increase', social_activity_2x_week: 'increase',
  sugar_intake_reduction: 'reduce', processed_food_reduction: 'reduce', alcohol_reduction: 'reduce',
  smoking_reduction: 'reduce', screen_time_reduction_before_bed: 'reduce',
  alcohol_elimination: 'avoid', smoking_cessation: 'avoid',
  sleep_7_to_9_hours: 'establish', sleep_onset_consistency: 'establish',
  mindfulness_10min_daily: 'establish', mindfulness_5min_daily: 'establish',
  stress_journaling_daily: 'establish', deep_breathing_daily: 'establish'
};
try {
  const part = resp.candidates[0].content.parts[0];
  const parsed = typeof part.text === 'string' ? JSON.parse(part.text) : part.text;
  for (const rx of (parsed.prescriptions || [])) {
    if (pillars.has(tidy(rx.pillar))) rx.pillar = tidy(rx.pillar);
    const category = tidy(rx.category);
    if (allowed.has(category)) rx.category = category;
    else if (categoryByBehavior[category]) rx.category = categoryByBehavior[category];
    else if (categoryByBehavior[tidy(rx.target_behavior)]) rx.category = categoryByBehavior[tidy(rx.target_behavior)];
  }
  part.text = JSON.stringify(parsed);
} catch (e) {
  // Leave malformed output untouched so Validation Gate returns the parse error.
}
return [{ json: resp }];

// Validation gate (mandatory design decision): parse the LLM JSON, validate every
// prescription and nudge against the enumerations, assign IDs, resolve nudge->
// prescription refs, and seed schedule_state. Any violation rejects the WHOLE
// batch (no partial writes) and returns the errors to the webhook caller.
//
// action_text is deliberately NOT enumerated: it is the clinician-owned execution
// step. It is still gated on presence and length so no unbounded or empty action
// can reach the Sheet, and target_behavior is written blank now that the fixed
// action catalogue is retired.

const ctx = $('Extract Input').first().json;
const resp = items[0].json;
const now = new Date().toISOString();

const PILLARS = ['nutrition','physical_activity','sleep','stress_management','substance_use','social_connection'];
const CATS = ['increase','reduce','maintain','avoid','establish'];
const NTYPE = ['reminder','reflection','challenge','affirmation'];
const TONE = ['encouraging','neutral_informational'];
const TEMPL = ['health_plan_reminder','hello_world'];
const ACTION_MAX = 1024;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const TIME_RE = /^([01]\d|2[0-3]):[0-5]\d$/;
const crypto = (function(){ try { return require('crypto'); } catch(e){ return { randomUUID: function(){ return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c){ var r = Math.random()*16|0; return (c==='x'?r:(r&3|8)).toString(16); }); } }; } })(); const uid = () => crypto.randomUUID();

let parsed;
try {
  const text = resp.candidates[0].content.parts[0].text;
  parsed = typeof text === 'string' ? JSON.parse(text) : text;
} catch (e) {
  return [{ json: { validation_passed: false, stage: 'parse', error: String(e) } }];
}

const P = parsed && parsed.prescriptions;
const N = parsed && parsed.nudges;
if (!Array.isArray(P) || !Array.isArray(N) || P.length === 0 || N.length === 0) {
  return [{ json: { validation_passed: false, stage: 'shape', error: 'prescriptions and nudges must be non-empty arrays' } }];
}

const errors = [];
const refMap = {};
const pillarByPrescription = {};

const prescriptions = P.map((p, i) => {
  const prescription_id = 'rx_' + uid();
  if (p.ref) refMap[p.ref] = prescription_id;
  pillarByPrescription[prescription_id] = p.pillar;
  if (!PILLARS.includes(p.pillar)) errors.push('rx[' + i + '] pillar: ' + p.pillar);
  if (!CATS.includes(p.category)) errors.push('rx[' + i + '] category: ' + p.category);
  const freq = parseInt(p.frequency_per_week, 10);
  const dur = parseInt(p.duration_weeks, 10);
  if (!(freq >= 1 && freq <= 7)) errors.push('rx[' + i + '] frequency_per_week: ' + p.frequency_per_week);
  if (!(dur >= 1 && dur <= 52)) errors.push('rx[' + i + '] duration_weeks: ' + p.duration_weeks);
  return {
    prescription_id,
    user_id: ctx.user.user_id,
    doctor_id: ctx.prescription_input.doctor_id || '',
    issued_date: ctx.prescription_input.issued_date || '',
    pillar: p.pillar, category: p.category, target_behavior: '',
    frequency_per_week: freq, duration_weeks: dur,
    prescription_raw_text: ctx.prescription_input.prescription_raw_text || '',
    status: 'active'
  };
});

const nudges = N.map((n, i) => {
  const nudge_id = 'ndg_' + uid();
  const prescription_id = refMap[n.prescription_ref] || (prescriptions[0] && prescriptions[0].prescription_id);
  if (!prescription_id) errors.push('ndg[' + i + '] unresolved prescription_ref: ' + n.prescription_ref);
  const action_text = String(n.action_text == null ? '' : n.action_text).trim();
  if (!NTYPE.includes(n.nudge_type)) errors.push('ndg[' + i + '] nudge_type: ' + n.nudge_type);
  if (!PILLARS.includes(n.pillar)) errors.push('ndg[' + i + '] pillar: ' + n.pillar);
  if (prescription_id && pillarByPrescription[prescription_id] && n.pillar !== pillarByPrescription[prescription_id]) {
    errors.push('ndg[' + i + '] pillar does not match its prescription: ' + n.pillar);
  }
  if (!action_text) errors.push('ndg[' + i + '] action_text is required');
  else if (action_text.length > ACTION_MAX) errors.push('ndg[' + i + '] action_text is longer than ' + ACTION_MAX + ' characters');
  if (n.tone_variant && !TONE.includes(n.tone_variant)) errors.push('ndg[' + i + '] tone_variant: ' + n.tone_variant);
  if (n.template_name && !TEMPL.includes(n.template_name)) errors.push('ndg[' + i + '] template_name: ' + n.template_name);
  if (!DATE_RE.test(n.scheduled_date || '')) errors.push('ndg[' + i + '] scheduled_date: ' + n.scheduled_date);
  if (!TIME_RE.test(n.scheduled_time || '')) errors.push('ndg[' + i + '] scheduled_time: ' + n.scheduled_time);
  if (!n.message_body || n.message_body.length > 1024) errors.push('ndg[' + i + '] message_body missing or too long');
  if (n.message_body_alt && n.message_body_alt.length > 1024) errors.push('ndg[' + i + '] message_body_alt too long');
  return {
    nudge_id, prescription_id, user_id: ctx.user.user_id,
    nudge_type: n.nudge_type, pillar: n.pillar, action_text,
    scheduled_date: n.scheduled_date, scheduled_time: n.scheduled_time,
    message_body: n.message_body || '', message_body_alt: n.message_body_alt || '',
    tone_variant: n.tone_variant || 'neutral_informational',
    template_name: (n.template_name || 'health_plan_reminder'), status: 'needs_review', sent_at: '', reviewed_at: '', week_number: 1, schedule_slot_id: ''
  };
});

if (errors.length) {
  return [{ json: { validation_passed: false, stage: 'enum', errors } }];
}

const schedule_state = nudges.map(n => ({
  schedule_id: 'sch_' + n.nudge_id, nudge_id: n.nudge_id, user_id: n.user_id,
  parent_nudge_id: n.nudge_id, status: 'needs_review', sent_at: '', delivered_at: '',
  wa_message_id: '', tone_sent: '', last_updated: now
}));

const uq = ctx.questionnaire || {};
const questionnaire = {
  questionnaire_id: 'qn_' + uid(), user_id: ctx.user.user_id, completed_at: now,
  age: parseInt(uq.age, 10), gender: uq.gender, activity_level: uq.activity_level,
  primary_goal: uq.primary_goal, preferred_nudge_time: uq.preferred_nudge_time,
  opt_in_whatsapp: !!uq.opt_in_whatsapp
};

const user = {
  user_id: ctx.user.user_id, name: ctx.user.name, phone: ctx.user.phone, email: ctx.user.email,
  created_at: ctx.user.created_at || now, user_status: ctx.user.user_status || 'active'
};

return [{ json: { validation_passed: true, user, questionnaire, prescriptions, nudges, schedule_state } }];

const user = $('Validation Gate').first().json.user;
user.doctor_id = $('Extract Input').first().json.prescription_input.doctor_id || '';
return [{ json: user }];
